//! Bit-exact parity with Pillow, driven by committed golden vectors.
//!
//! `tests/fixtures/pillow_golden/pillow_golden.jsonl` is generated by
//! `scripts/golden/gen_pillow_golden.py` from Pillow + numpy (the oracle;
//! development-time only). Every case is replayed here and compared byte
//! for byte: a mismatch is an implementation bug, never a reason to edit
//! the vector.
//!
//! Covered: `Image.resize` for L / LA / RGB / RGBA (premultiplied alpha),
//! `I;16` and `F` rasters, `reducing_gap`, `Image.reduce`, and the
//! `convert` paths exposed by the kit.

use sillstone_image::raster::{
    Cmyk, Gray, Image, La, Layout, ResamplingFilter, Rgb, Rgba, cmyk_to_rgb, reduce, resize_f32,
    resize_with_gap, rgb_plane_to_l, rgb_to_cmyk, rgb_to_l,
};

const GOLDEN: &str = include_str!("fixtures/pillow_golden/pillow_golden.jsonl");

/// One golden case; every field is a string, a number or null.
struct Case {
    id: String,
    op: String,
    mode: String,
    w: u32,
    h: u32,
    ow: u32,
    oh: u32,
    filter: Option<String>,
    gap: Option<f64>,
    to: Option<String>,
    input: Vec<u8>,
    expected: Vec<u8>,
}

/// Minimal parser for one flat JSON object (string / number / null values,
/// no escapes beyond `\"` and `\\`): enough for the generator's output,
/// without a JSON dependency.
fn parse_object(line: &str) -> Vec<(String, String)> {
    let b = line.as_bytes();
    let mut i = 0;
    let mut out = Vec::new();
    let skip_ws = |i: &mut usize| {
        while *i < b.len() && (b[*i] == b' ' || b[*i] == b',') {
            *i += 1;
        }
    };
    let string = |i: &mut usize| -> String {
        assert_eq!(b[*i], b'"');
        *i += 1;
        let mut s = String::new();
        while b[*i] != b'"' {
            if b[*i] == b'\\' {
                *i += 1;
            }
            s.push(b[*i] as char);
            *i += 1;
        }
        *i += 1;
        s
    };
    assert_eq!(b[i], b'{');
    i += 1;
    loop {
        skip_ws(&mut i);
        if b[i] == b'}' {
            break;
        }
        let key = string(&mut i);
        assert_eq!(b[i], b':');
        i += 1;
        let val = if b[i] == b'"' {
            string(&mut i)
        } else {
            let start = i;
            while b[i] != b',' && b[i] != b'}' {
                i += 1;
            }
            line[start..i].to_string()
        };
        out.push((key, val));
    }
    out
}

fn unhex(s: &str) -> Vec<u8> {
    assert_eq!(s.len() % 2, 0);
    (0..s.len() / 2)
        .map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).expect("hex"))
        .collect()
}

fn cases() -> Vec<Case> {
    let mut lines = GOLDEN.lines();
    let meta = lines.next().expect("provenance line");
    assert!(meta.contains("\"_provenance\""), "first line is provenance");
    lines
        .filter(|l| !l.is_empty())
        .map(|l| {
            let kv = parse_object(l);
            let get = |k: &str| -> &str { &kv.iter().find(|(key, _)| key == k).expect("key").1 };
            let opt = |k: &str| -> Option<String> {
                let v = get(k);
                (v != "null").then(|| v.to_string())
            };
            let num = |k: &str| get(k).parse::<u32>().unwrap_or(0);
            Case {
                id: get("id").to_string(),
                op: get("op").to_string(),
                mode: get("mode").to_string(),
                w: num("w"),
                h: num("h"),
                ow: num("ow"),
                oh: num("oh"),
                filter: opt("filter"),
                gap: opt("gap").map(|g| g.parse().expect("gap")),
                to: opt("to"),
                input: unhex(get("input")),
                expected: unhex(get("expected")),
            }
        })
        .collect()
}

fn filter_of(name: &str) -> ResamplingFilter {
    match name {
        "nearest" => ResamplingFilter::Nearest,
        "box" => ResamplingFilter::Box,
        "bilinear" => ResamplingFilter::Bilinear,
        "bicubic" => ResamplingFilter::Bicubic,
        "lanczos" => ResamplingFilter::Lanczos,
        other => panic!("unknown filter {other}"),
    }
}

fn u16s(bytes: &[u8]) -> Vec<u16> {
    bytes
        .chunks_exact(2)
        .map(|c| u16::from_le_bytes([c[0], c[1]]))
        .collect()
}

fn f32s(bytes: &[u8]) -> Vec<f32> {
    bytes
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect()
}

fn run_resize<L: Layout>(case: &Case) -> Vec<u8> {
    let img = Image::<L, u8>::from_vec(case.w, case.h, case.input.clone()).expect("image");
    let filter = filter_of(case.filter.as_deref().expect("filter"));
    resize_with_gap(&img, case.ow, case.oh, filter, case.gap)
        .expect("resize")
        .as_slice()
        .to_vec()
}

fn run_reduce<L: Layout>(case: &Case) -> Vec<u8> {
    let img = Image::<L, u8>::from_vec(case.w, case.h, case.input.clone()).expect("image");
    reduce(&img, case.ow, case.oh)
        .expect("reduce")
        .as_slice()
        .to_vec()
}

/// Replays `cases` with `run`, collecting the ids that differ.
fn check(ops: &[&str], run: impl Fn(&Case) -> Option<Vec<u8>>) -> usize {
    let mut seen = 0;
    let mut bad = Vec::new();
    for case in cases().iter().filter(|c| ops.contains(&c.op.as_str())) {
        let Some(got) = run(case) else { continue };
        seen += 1;
        if got != case.expected {
            let first = got
                .iter()
                .zip(&case.expected)
                .position(|(a, b)| a != b)
                .unwrap_or(got.len().min(case.expected.len()));
            bad.push(format!("{} (first diff at byte {first})", case.id));
        }
    }
    assert!(
        bad.is_empty(),
        "{} of {seen} cases differ:\n{}",
        bad.len(),
        bad.join("\n")
    );
    seen
}

#[test]
fn resize_8bit_modes_match_pillow() {
    let n = check(&["resize"], |c| match c.mode.as_str() {
        "L" => Some(run_resize::<Gray>(c)),
        "LA" => Some(run_resize::<La>(c)),
        "RGB" => Some(run_resize::<Rgb>(c)),
        "RGBA" => Some(run_resize::<Rgba>(c)),
        _ => None,
    });
    assert!(n >= 100, "expected the 8-bit resize cases, saw {n}");
}

#[test]
fn resize_i16_matches_pillow() {
    let n = check(&["resize"], |c| {
        if c.mode != "I;16" {
            return None;
        }
        let img = Image::<Gray, u16>::from_vec(c.w, c.h, u16s(&c.input)).expect("image");
        let out = resize_with_gap(&img, c.ow, c.oh, filter_of(c.filter.as_deref()?), None)
            .expect("resize");
        Some(
            out.as_slice()
                .iter()
                .flat_map(|v| v.to_le_bytes())
                .collect(),
        )
    });
    assert!(n >= 20, "expected the I;16 resize cases, saw {n}");
}

#[test]
fn resize_f32_matches_pillow() {
    let n = check(&["resize"], |c| {
        if c.mode != "F" {
            return None;
        }
        let out = resize_f32(
            &f32s(&c.input),
            c.w,
            c.h,
            1,
            c.ow,
            c.oh,
            filter_of(c.filter.as_deref()?),
        )
        .expect("resize");
        Some(out.iter().flat_map(|v| v.to_le_bytes()).collect())
    });
    assert!(n >= 20, "expected the F resize cases, saw {n}");
}

#[test]
fn reduce_matches_pillow() {
    let n = check(&["reduce"], |c| match c.mode.as_str() {
        "L" => Some(run_reduce::<Gray>(c)),
        "LA" => Some(run_reduce::<La>(c)),
        "RGB" => Some(run_reduce::<Rgb>(c)),
        "RGBA" => Some(run_reduce::<Rgba>(c)),
        _ => None,
    });
    assert!(n >= 19, "expected the reduce cases, saw {n}");
}

/// Applies `f` to every `from`-channel pixel of `input`, concatenating the
/// `to`-channel results.
fn map_pixels(input: &[u8], from: usize, f: impl Fn(&[u8], &mut Vec<u8>)) -> Vec<u8> {
    let mut out = Vec::new();
    for px in input.chunks_exact(from) {
        f(px, &mut out);
    }
    out
}

#[test]
fn convert_matches_pillow() {
    let n = check(&["convert"], |c| {
        let to = c.to.as_deref()?;
        Some(match (c.mode.as_str(), to) {
            ("RGB", "L") => {
                let planar = rgb_plane_to_l(&c.input, 3, c.input.len() / 3);
                let scalar = map_pixels(&c.input, 3, |p, o| o.push(rgb_to_l(p[0], p[1], p[2])));
                assert_eq!(planar, scalar, "{}: SIMD route differs from scalar", c.id);
                planar
            }
            ("RGBA", "L") => map_pixels(&c.input, 4, |p, o| o.push(rgb_to_l(p[0], p[1], p[2]))),
            ("RGBA", "RGB") => {
                let img = Image::<Rgba, u8>::from_vec(c.w, c.h, c.input.clone()).expect("image");
                img.to_rgb().as_slice().to_vec()
            }
            ("RGB", "RGBA") => {
                let img = Image::<Rgb, u8>::from_vec(c.w, c.h, c.input.clone()).expect("image");
                img.to_rgba().as_slice().to_vec()
            }
            ("L", "RGB") => {
                let img = Image::<Gray, u8>::from_vec(c.w, c.h, c.input.clone()).expect("image");
                img.to_rgb().as_slice().to_vec()
            }
            ("L", "RGBA") => {
                let img = Image::<Gray, u8>::from_vec(c.w, c.h, c.input.clone()).expect("image");
                img.to_rgba().as_slice().to_vec()
            }
            ("RGB", "CMYK") => map_pixels(&c.input, 3, |p, o| {
                let (cy, m, y, k) = rgb_to_cmyk(p[0], p[1], p[2]);
                o.extend_from_slice(&[cy, m, y, k]);
            }),
            ("CMYK", "RGB") => {
                let img = Image::<Cmyk, u8>::from_vec(c.w, c.h, c.input.clone()).expect("image");
                let by_pixel = map_pixels(&c.input, 4, |p, o| {
                    let (r, g, b) = cmyk_to_rgb(p[0], p[1], p[2], p[3]);
                    o.extend_from_slice(&[r, g, b]);
                });
                assert_eq!(img.to_rgb().as_slice(), by_pixel.as_slice());
                by_pixel
            }
            other => panic!("unhandled conversion {other:?}"),
        })
    });
    assert!(n >= 11, "expected the convert cases, saw {n}");
}
